import{_ as t,o,c as l,ai as e}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/settings.md","filePath":"zh/guide/settings.md"}'),r={name:"zh/guide/settings.md"};function i(s,a,n,d,h,c){return o(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h1><p>设置页用于配置 Ollama 连接、默认模型参数和应用偏好。</p><p><strong>侧边栏位置：</strong> 设置 <strong>路由：</strong> <code>/settings</code></p><h2 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to &quot;连接&quot;">​</a></h2><h3 id="ollama-地址" tabindex="-1">Ollama 地址 <a class="header-anchor" href="#ollama-地址" aria-label="Permalink to &quot;Ollama 地址&quot;">​</a></h3><p>设置 Ollama 的运行地址。默认值：<code>http://localhost:11434</code>。</p><h3 id="连接测试" tabindex="-1">连接测试 <a class="header-anchor" href="#连接测试" aria-label="Permalink to &quot;连接测试&quot;">​</a></h3><p>点击<strong>测试连接</strong>可验证 LLMxRay 能否访问到 Ollama。结果显示为：</p><ul><li><strong>已连接</strong>（绿色）—— Ollama 可访问且有响应</li><li><strong>未连接</strong>（红色）—— 请检查 <code>ollama serve</code> 是否在运行</li></ul><div class="tip custom-block"><p class="custom-block-title">远程 Ollama</p><p>如果 Ollama 运行在另一台机器上，请填入它的 IP 和端口（例如 <code>http://192.168.1.100:11434</code>）。同时请确认 <code>vite.config.ts</code> 中的代理已更新，或远程 Ollama 实例已正确配置 CORS。</p></div><h2 id="默认参数" tabindex="-1">默认参数 <a class="header-anchor" href="#默认参数" aria-label="Permalink to &quot;默认参数&quot;">​</a></h2><h3 id="温度" tabindex="-1">温度 <a class="header-anchor" href="#温度" aria-label="Permalink to &quot;温度&quot;">​</a></h3><p>控制模型输出的随机性。界面上配有<strong>可视化刻度</strong>与<strong>讲解式提示</strong>：</p><table tabindex="0"><thead><tr><th>取值</th><th>效果</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>确定性 —— 总是选择概率最高的 token</td></tr><tr><td><strong>0.7</strong></td><td>平衡 —— 大多数场景的默认值</td></tr><tr><td><strong>1.0 以上</strong></td><td>有创造性 —— 输出更多样，有时会出人意料</td></tr></tbody></table><h3 id="上下文长度" tabindex="-1">上下文长度 <a class="header-anchor" href="#上下文长度" aria-label="Permalink to &quot;上下文长度&quot;">​</a></h3><p>设置模型能够纳入考虑的最大 token 数。数值越大，能支撑的对话越长，但也会占用更多内存。</p><p>这两个参数都配有可视化刻度，并用平实的语言解释每项设置的作用。</p><h2 id="模型目录" tabindex="-1">模型目录 <a class="header-anchor" href="#模型目录" aria-label="Permalink to &quot;模型目录&quot;">​</a></h2><p>模型标签页（也可从侧边栏进入）提供：</p><ul><li>可浏览的已安装模型目录</li><li>能力检测标识（推理、视觉、嵌入、工具调用）</li><li>架构细节与参数量</li><li>便于并排评估模型的对比功能</li></ul><p>完整说明见<a href="./models.html">模型</a>一章。</p><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><p>可在以下模式间切换：</p><ul><li><strong>深色模式</strong> —— 默认，适合长时间使用</li><li><strong>浅色模式</strong> —— 高对比度的替代方案</li><li><strong>跟随系统</strong> —— 随操作系统的偏好切换</li></ul><p>主题切换按钮在顶栏中同样可用。</p><h2 id="google-oauth2" tabindex="-1">Google OAuth2 <a class="header-anchor" href="#google-oauth2" aria-label="Permalink to &quot;Google OAuth2&quot;">​</a></h2><p>对于需要访问 Google 服务（日历、Gmail）的工具工坊模板，你可以配置 OAuth2：</p><ol><li>填入你在 Google Cloud Console 中的 <strong>Client ID</strong></li><li>点击<strong>连接</strong>进行授权</li><li>连接完成后，基于 Google 的工具即可访问你的账号</li></ol><div class="warning custom-block"><p class="custom-block-title">隐私</p><p>OAuth 令牌只保存在你本地的浏览器中。LLMxRay 绝不会把你的凭据发送到任何外部服务器。</p></div><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>先用默认值</strong> —— 默认温度（0.7）和上下文长度对大多数模型都够用。</li><li>如果内存 / 显存吃紧，就<strong>调小上下文长度</strong>。</li><li>遇到「没有模型」的问题时，连接测试是最快的排查手段。</li></ul>',31)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
